window.PORTAL={"day": 18, "title": "Tetralogy of Fallot & Cyanotic CHD", "docTitle": "DAY 18 — FIVE-HOUR ENHANCED NEET-SS + ICP PAEDIATRICS | CONSOLIDATED EDITION", "subtitle": ["16 October 2026 • Tetralogy of Fallot and cyanotic congenital heart disease", "QA classification: five-stage AI-editorial reviewed educational edition; no claim of external clinician review or paid-textbook consultation. Consult verified institutional protocols for bedside decisions."], "source": "source/Day18_Five_Hour_Reviewed_Retest_Names_FIXED.docx", "pages": [{"id": "overview", "title": "Overview", "group": "Start", "kind": "overview", "sections": [{"title": "", "blocks": [{"t": "p", "html": "16 October 2026 • Tetralogy of Fallot and cyanotic congenital heart disease"}, {"t": "p", "html": "QA classification: five-stage AI-editorial reviewed educational edition; no claim of external clinician review or paid-textbook consultation. Consult verified institutional protocols for bedside decisions."}, {"t": "p", "html": "Revision record: source V9 question bank integrated with review corrections, five-hour schedule, corrected answer-option alignment, documented notebook and numerical drills, and question-level independent AI second-solving."}, {"t": "p", "html": "The additional Day 14 calculation-error retests at the end of this document are unscored extras, NOT substitutions for the 75 base MCQs or 9 notebook MCQs."}, {"t": "p", "html": "DAY 18 | TOF + CYANOTIC CHD"}, {"t": "p", "html": "Friday 16 October 2026  •  Locked 73-day plan  •  Foundation-to-advanced phase  •  5-hour expanded study"}, {"t": "p", "html": "75 original base MCQs (revised editorial difficulty mix: 7 Basic / Recall, 13 Conceptual, 27 Clinical / Application, 20 High Difficulty, 8 Integrated / Rank Differentiating) + 9 separate notebook retests + 8 extra Friday calculations. Answers and all explanations are separated from the question bank. No Day 19 lesion-specific deep dive."}, {"t": "table", "head": ["Time", "Study block", "Goal"], "rows": [["00–70 min", "Deep anatomy, embryology, mechanisms and pathophysiology", "Explain and reconstruct TOF hemodynamic chains"], ["70–135 min", "Clinical cases, spells, diagnostics and Indian management algorithms", "Work through cases and flowcharts without looking"], ["135–235 min", "75 base MCQs plus separate notebook MCQ retests", "Solve before any answer key; record confidence and time"], ["235–270 min", "Four-option explanation review and examiner traps", "Document close-distractor errors and why alternatives fail"], ["270–300 min", "Active Recall, Friday calculations and rapid revision", "Retest due notebook concepts and log R1/R2/R3"]]}]}, {"title": "Coverage Traceability Matrix", "h1": "Coverage Traceability Matrix", "blocks": [{"t": "table", "head": ["Objective", "Content / stations", "Base MCQs"], "rows": [["O1 TOF morphology / embryology", "Notes 1; Fig 1; Station 1", "1–2, 4–6, 17, 37–38, 57, 59, 64"], ["O2 cyanotic physiology / hemodynamics", "Notes 2; Fig 2; Station 2", "3, 8, 10–12, 20, 28, 48, 61–62"], ["O3 hypercyanotic spell rescue", "Algorithm A; Cases 1–3", "9, 13, 21–27, 49–50, 55, 60, 68"], ["O4 duct-dependent pulmonary flow", "Fig 4; Algorithm B; Cases 4, 8", "14–15, 18, 29–30, 35–36, 56, 58, 71"], ["O5 investigation &amp; differential", "Fig 3; Stations 3–5", "45–46, 54, 63, 73"], ["O6 intervention and follow-up", "Indian table; Cases 5–7", "16, 19, 31–34, 39–40, 42–44, 47, 51–53, 65–67, 69, 72, 74–75"], ["O7 genetics and variants", "Notes 4; Cases 6, 9", "7, 41, 70"], ["O8 personal error repair", "9 extra retests + Active Recall queue", "Q76–84 (not counted in base 75)"]]}]}]}, {"id": "part-1", "title": "Morphology, Embryology and Core Hemodynamics", "eyebrow": "Part 1", "group": "Study Notes", "kind": "notes", "sections": [{"title": "", "blocks": [{"t": "list", "ordered": false, "items": ["Four features: large malalignment VSD; aorta overriding the septum; right ventricular outflow tract obstruction (RVOTO); RV hypertrophy (secondary consequence).", "Embryology: anterosuperior displacement of infundibular/conal septum explains VSD, override and subpulmonary narrowing.", "Large VSD permits near equal ventricular systolic pressures. Severity of RVOTO relative to SVR determines pulmonary versus systemic flow and cyanosis.", "Pink TOF: relatively mild obstruction, preserved pulmonary flow and initially near-normal SpO2. Cyanosis can increase as obstruction becomes more important.", "RVOT ejection murmur is often loud with moderate flow; during severe tet spell murmur may soften as flow falls. Single S2/soft P2 and RVH/right axis are classic clues."]}, {"t": "img", "src": "img/image1.png", "alt": ""}, {"t": "p", "html": "<em>Figure 1. Four-chamber schematic; arrows are conceptual and not scaled to real flow.</em>"}]}]}, {"id": "part-2", "title": "Tet Spell: Dynamic Vicious Cycle and Rescue", "eyebrow": "Part 2", "group": "Study Notes", "kind": "notes", "sections": [{"title": "", "blocks": [{"t": "list", "ordered": false, "items": ["Typical age: early infancy (often 2–6 months); triggers crying, feeding, fever, defecation, dehydration, anesthesia.", "Hyperpnea + deepening cyanosis + softer/disappearing RVOT murmur ± irritability, syncope or convulsions. A quiet murmur during a spell is a danger sign.", "Mechanism: adrenergic infundibular contraction / reduced preload / reduced SVR → greater RVOTO and R-to-L VSD flow → hypoxemia → hyperpnea and more adrenergic drive.", "Acute management is monitored and escalated: ABC, calm/knee-chest, oxygen, vascular access, cautious isotonic fluid if needed, analgesia/sedation, specialist beta blockade and SVR support; refractory events require airway/cardiac intervention.", "Do not use vasodilators or unmonitored beta agonists as reflex treatment; their physiologic effects may worsen R-to-L shunting."]}, {"t": "img", "src": "img/image2.png", "alt": ""}, {"t": "p", "html": "<em>Figure 2. Dynamic spell mechanism and leverage points; order of treatment depends on severity and local emergency protocol.</em>"}]}]}, {"id": "part-3", "title": "Cyanotic CHD Initial Assessment (Today: General Framework Only)", "eyebrow": "Part 3", "group": "Study Notes", "kind": "notes", "sections": [{"title": "", "blocks": [{"t": "table", "head": ["Pattern", "High-yield possibilities", "Key discriminator / immediate action"], "rows": [["Oligemic lungs + RVH / right axis", "TOF, critical PS, severe Ebstein", "Echo RVOT and ductal flow; PGE1 if duct-dependent pulmonary flow"], ["Oligemic lungs + LVH / superior axis", "Tricuspid atresia, some pulmonary atresia", "Assess ventricular anatomy and pulmonary flow"], ["Cyanosis with little distress", "Mixing lesions including d-TGA", "Urgent echo; PGE1 when indicated; detailed TGA deferred to Day 19"], ["Cyanosis + marked edema/distress", "Obstructed pulmonary venous return", "Urgent echo and surgical referral; do not assume PPHN"], ["Shock after ductal constriction", "Duct-dependent systemic flow", "PGE1, cautious stabilization and urgent echo"], ["Pre/postductal SpO2 difference", "Ductal shunt/PPHN/arch lesion", "Helpful clue but not sufficient to name lesion"]]}, {"t": "p", "html": "Clinical safety clarification: In suspected critical congenital heart disease, promptly assess pre- and postductal oxygen saturation, perfusion, pulses and glucose and obtain urgent pediatric cardiology/echocardiography assessment. Consider prostaglandin E1 when duct-dependent circulation is suspected, following a verified institutional neonatal protocol. Do not apply a single SpO2 target to every TOF patient."}]}]}, {"id": "part-4", "title": "Variants, Imaging, Genetic Association", "eyebrow": "Part 4", "group": "Study Notes", "kind": "notes", "sections": [{"title": "", "blocks": [{"t": "list", "ordered": false, "items": ["TOF with pulmonary atresia: pulmonary blood supply may come from PDA and/or major aortopulmonary collateral arteries (MAPCAs). Map branch PA confluence and collaterals before palliation/unifocalization.", "Absent pulmonary valve syndrome: massively dilated pulmonary arteries can compress bronchi; respiratory compromise may dominate over classic oligemic TOF picture.", "Coronary crossing RVOT (e.g., LAD from RCA) alters RVOT incision/conduit strategy; coronary and pulmonary annulus mapping are mandatory preoperative concerns.", "22q11.2 deletion can accompany conotruncal disease; evaluate palatal findings, calcium, immune status and family counselling where indicated.", "CXR classic: boot-shaped silhouette, concave pulmonary artery segment, reduced pulmonary vascular markings; ECG: right axis and RVH. Neither replaces echo."]}, {"t": "img", "src": "img/image3.png", "alt": ""}, {"t": "p", "html": "<em>Figure 3. Simplified silhouette for pattern recognition only; NOT a real radiograph.</em>"}, {"t": "img", "src": "img/image4.png", "alt": ""}, {"t": "p", "html": "<em>Figure 4. Ductal supply is crucial when antegrade pulmonary flow is absent or nearly absent.</em>"}]}]}, {"id": "part-5", "title": "Complications, Anatomy Extras and Spell-Management Details", "eyebrow": "Part 4A", "group": "Study Notes", "kind": "notes", "sections": [{"title": "", "blocks": [{"t": "list", "ordered": false, "items": ["Complications of unrepaired or cyanotic TOF: brain abscess (fever, headache, focal signs; image before lumbar puncture), cerebral arterial or venous thrombosis (dehydration, iron deficiency, hyperviscosity, mostly in infants and toddlers), infective endocarditis (cultures before antibiotics), polycythemia, coagulopathy, clubbing and hypercyanotic spells.", "Anatomy extras: a right aortic arch occurs in about a quarter of patients; pentalogy of Fallot is TOF with an ASD; coronary anomalies (for example LAD from the RCA) occur in a minority; a small pulmonary annulus (low Z-score, centre-specific cut-off) favours a transannular patch.", "Spell ladder: knee-chest, oxygen, morphine (reduces agitation and hyperpnea), fluid if hypovolemic, sodium bicarbonate for significant acidosis, IV propranolol or esmolol, phenylephrine for SVR, ketamine or sedation with airway control, then urgent surgery or palliation. Exact medication doses, routes and escalation triggers must be taken from a verified local paediatric cardiac emergency protocol; the previous unverified teaching-dose examples have been withdrawn.", "Palliation: a modified BT shunt (subclavian to pulmonary artery graft) raises pulmonary flow pending repair; too large a shunt overcirculates the lungs and steals systemic flow."]}]}]}, {"id": "part-6", "title": "Indian Consensus Intervention Timing and Surveillance", "eyebrow": "Part 5", "group": "Study Notes", "kind": "notes", "sections": [{"title": "", "blocks": [{"t": "table", "head": ["Clinical state", "India-specific consensus (Saxena et al., 2019)", "Important qualification"], "rows": [["Stable / minimally cyanosed TOF", "Total repair at 6–12 months or earlier by centre policy", "Do not wait for a spell"], ["Significant cyanosis/spells &lt;6 months", "Early total repair OR palliation (BT shunt, duct/RVOT stent, selected balloon procedure)", "Anatomy, weight, coronary/PA mapping, expertise"], ["Severe refractory spell", "Emergency intervention/repair assessment", "Not outpatient watchful waiting"], ["TOF pulmonary atresia/MAPCAs", "Individualized staged reconstruction / unifocalization", "Must map every lung blood-supply source"], ["Postrepair", "Lifelong congenital cardiac follow-up", "PR, RV dilation, RVOTO, arrhythmias, residual VSD, IE risk"]]}, {"t": "p", "html": "Long-term: after transannular patch monitor pulmonary regurgitation and RV dilation; ECG/Holter and CMR are used selectively for arrhythmia and RV volumes. Indian 2019 consensus includes severe RVEDVi &gt;160 mL/m² or RVESVi &gt;80 mL/m² among pulmonary valve replacement considerations, NOT stand-alone automatic surgery thresholds."}]}]}, {"id": "part-7", "title": "Five-Hour Deep-Dive: Exam-Relevant TOF Reasoning", "eyebrow": "Part N", "group": "Study Notes", "kind": "notes", "sections": [{"title": "", "blocks": [{"t": "p", "html": "Expanded within the assigned Day 18 topic only. These modules add clinical depth without moving future lesions into today’s syllabus."}]}, {"title": "Module 1 — Flow partition and the pink-to-blue continuum", "blocks": [{"t": "p", "html": "In TOF with a large nonrestrictive malalignment VSD, right and left ventricular systolic pressures can be nearly equal. A simple “VSD size predicts severity” heuristic is misleading. Instead, reason from RVOT obstruction relative to systemic afterload, preload, pulmonary vascular resistance and dynamic infundibular tone."}, {"t": "p", "html": "Micro-case: A pink TOF infant has SpO2 95% at rest. During crying, SpO2 falls to 75% and the systolic murmur softens. The drop in forward RVOT flow, not spontaneous relief of obstruction, explains the softer murmur. Discuss which changes in SVR, catecholamines and preload are plausible and which cannot be inferred without echo."}, {"t": "p", "html": "Exam discriminator: Loud RVOT murmur does not imply more severe cyanosis; in near-atresia less forward blood crosses the obstruction so the murmur may be faint."}]}, {"title": "Module 2 — Hypercyanotic spell: simultaneous priorities", "blocks": [{"t": "p", "html": "Separate initial low-risk maneuvers (call for help, ABC, monitoring, calm positioning, supplemental oxygen, evaluation of perfusion and hydration) from expert-only therapy (titrated sedation, beta blockade, phenylephrine and airway control). Do not force a rigid drug ladder when the child is obtunded or shocked."}, {"t": "p", "html": "Persistent cyanosis despite oxygen does not justify abandoning oxygen. A large intracardiac right-to-left component limits its corrective effect; restoring effective pulmonary flow remains essential."}, {"t": "p", "html": "Acidosis is primarily addressed by restoring oxygen delivery, ventilation and perfusion. Bicarbonate is not a universal or first-line tet-spell step; specialist/local emergency protocols govern exceptional use."}]}, {"title": "Module 3 — Duct-dependent flow versus ordinary TOF", "blocks": [{"t": "p", "html": "In a neonate with near pulmonary atresia, the duct may carry essential pulmonary blood flow. Serial saturation decline as ductal flow decreases is urgent; monitored PGE1 may preserve the duct while expert echo maps antegrade flow and PA/MAPCA connections."}, {"t": "p", "html": "In a thriving infant with stable classical TOF and adequate antegrade RVOT blood flow, PGE1 is not automatically indicated. Duct dependence is physiology, not a synonym for a named lesion."}, {"t": "p", "html": "Decision exercise: Contrast a stable 8-month-old with mild cyanosis and a day-2 neonate deteriorating as the PDA constricts; both share TOF anatomy but require very different immediate decisions."}]}, {"title": "Module 4 — Anatomy-led timing and surgical trade-offs", "blocks": [{"t": "p", "html": "The verified Indian 2019 consensus supports total repair at 6–12 months for stable minimally cyanosed infants, earlier according to institutional policy. Significant spells/cyanosis under six months prompt consideration of early complete repair or palliation according to anatomy and expertise."}, {"t": "p", "html": "Preoperative decisions include pulmonary annulus size, RVOT obstruction level, branch PA anatomy and anomalous coronary route. A transannular patch may relieve obstruction yet leave long-term pulmonary regurgitation. Valve preservation may decrease regurgitation but must avoid clinically important residual obstruction."}, {"t": "p", "html": "An anomalous LAD crossing the anterior RVOT changes safe incision and conduit strategy. The correct examination answer should rarely be an automatic surgical method without the coronary and PA information."}]}, {"title": "Module 5 — Late repaired TOF: integrated interpretation", "blocks": [{"t": "p", "html": "Follow-up targets residual RVOTO, free pulmonary regurgitation, RV enlargement/function, arrhythmias, exercise capacity and residual VSD. A normal resting SpO2 does not rule out important late disease."}, {"t": "p", "html": "CMR RVEDVi &gt;160 mL/m² or RVESVi &gt;80 mL/m² appears within Indian 2019 consensus considerations for pulmonary valve replacement, but not as a standalone trigger; symptoms, ventricular function, gradients, exercise trends and rhythm findings must be integrated."}, {"t": "p", "html": "Exam discriminator: Sustained VT plus severe PR and RV dysfunction requires an adult congenital cardiology/electrophysiology plan, not treatment of a single echo variable."}]}, {"title": "Module 6 — Five-hour allocation (300 minutes)", "blocks": [{"t": "p", "html": "00–70 min: morphology, embryology, right-to-left physiology and comparative hemodynamics. 70–135 min: hypercyanotic spells, neonatal ductal emergencies, Indian management and long-term consequences."}, {"t": "p", "html": "135–235 min: attempt 75 base MCQs and nine separate retests, recording sure/unsure/guessed. 235–270 min: revisit wrong and guessed MCQs using full A–D explanations. 270–300 min: visual interpretation, Active Recall, rapid revision and Friday calculations. This is a target allocation; complete examination-style error analysis may extend beyond five hours."}]}]}, {"id": "numbers", "title": "Must-Know Numbers", "group": "Quick Reference", "kind": "notes", "sections": [{"title": "", "blocks": [{"t": "table", "head": ["Number / anchor", "Meaning", "Source / caution"], "rows": [["6–12 months", "Elective repair for stable minimally cyanosed TOF", "Indian 2019 consensus; earlier if indicated"], ["&lt;6 months + refractory symptoms", "Consider earlier repair or palliation", "Indian 2019 consensus"], ["PGE1 for suspected duct-dependent flow", "Keeps the duct open until intervention", "High-alert drug: apnea and monitoring; dose per local neonatal protocol"], ["75–85%", "Selected duct-dependent systemic-flow target", "Not a generic TOF saturation target"], ["RVEDVi &gt;160 or RVESVi &gt;80 mL/m²", "One factor in post-TOF pulmonary valve assessment", "2019 Indian consensus; specialist decision"], ["2–6 months", "Common spell age window", "Teaching epidemiology, not a strict cutoff"]]}]}]}, {"id": "tables", "title": "Tables & Algorithms", "group": "Quick Reference", "kind": "notes", "sections": [{"title": "Algorithm A — Hypercyanotic Spell", "h1": "Algorithm A — Hypercyanotic Spell", "blocks": [{"t": "list", "ordered": true, "items": ["Recognize: known/suspected TOF + acute cyanosis, hyperpnea, softer RVOT murmur; call emergency cardiac help.", "Stabilize ABC, monitor SpO2/ECG/BP, keep child calm, knee-to-chest position; give supplemental oxygen.", "Obtain IV/IO access, assess dehydration, perfusion, glucose, acid-base status; cautious isotonic bolus when indicated.", "If persistent, monitored analgesia/sedation and specialist-guided beta blocker and/or phenylephrine to increase SVR.", "If severe or refractory: resuscitation-team airway/ventilation, cardiology and urgent cath/surgery/palliation; treat precipitant."]}]}, {"title": "Algorithm B — Cyanotic Neonate", "h1": "Algorithm B — Cyanotic Neonate", "blocks": [{"t": "list", "ordered": true, "items": ["Confirm central cyanosis (tongue/oral mucosa) and measure preductal and postductal SpO2.", "ABC, temperature, glucose, perfusion, lactate, four-limb pulses/BP; evaluate pulmonary and infectious mimics simultaneously.", "Obtain urgent expert echocardiography without delaying for nonessential tests.", "If duct-dependent pulmonary/systemic flow is suspected, initiate PGE1 under monitored neonatal protocol with apnea readiness.", "Transfer promptly to pediatric cardiac center; tailor oxygen and fluids to confirmed physiology."]}]}]}, {"id": "cases", "title": "Clinical Cases", "group": "Practice", "kind": "cases", "sections": [{"title": "Case 1 — First spell", "blocks": [{"t": "p", "html": "Stem: 4-month TOF, crying, deep cyanosis, hyperpnea, softer murmur."}, {"t": "p", "html": "Best next step: Calm, knee-chest, ABC/O2, urgent monitored escalation."}, {"t": "p", "html": "Mechanism / trap: Less RVOT flow means a softer murmur; do not mistake it for improvement."}]}, {"title": "Case 2 — Dehydrated spell", "blocks": [{"t": "p", "html": "Stem: 5-month TOF, fever/diarrhea, hypotension and spell."}, {"t": "p", "html": "Best next step: Assess preload and give cautious isotonic volume if indicated; specialist SVR/beta-blocker support."}, {"t": "p", "html": "Mechanism / trap: Hypovolemia and low SVR amplify R-to-L shunt."}]}, {"title": "Case 3 — Refractory spell", "blocks": [{"t": "p", "html": "Stem: 7-month child with prolonged spell and reduced consciousness."}, {"t": "p", "html": "Best next step: Resuscitation airway/circulation and urgent cardiac intervention."}, {"t": "p", "html": "Mechanism / trap: Knee-chest alone is insufficient in collapse."}]}, {"title": "Case 4 — Duct-dependent TOF", "blocks": [{"t": "p", "html": "Stem: Day-2 newborn, severe RVOTO, saturation falling as PDA constricts."}, {"t": "p", "html": "Best next step: Urgent echo and PGE1 under monitoring."}, {"t": "p", "html": "Mechanism / trap: PDA may be sole effective pulmonary supply."}]}, {"title": "Case 5 — Elective repair", "blocks": [{"t": "p", "html": "Stem: 8-month minimally cyanosed TOF, good PAs, no spells."}, {"t": "p", "html": "Best next step: Total repair in 6–12-month Indian window."}, {"t": "p", "html": "Mechanism / trap: Absence of spells does not mean no repair."}]}, {"title": "Case 6 — Crossing LAD", "blocks": [{"t": "p", "html": "Stem: TOF with LAD from RCA crossing RVOT."}, {"t": "p", "html": "Best next step: Plan coronary-sparing approach; may need modified RVOT strategy."}, {"t": "p", "html": "Mechanism / trap: Blind RVOT incision risks coronary injury."}]}, {"title": "Case 7 — Long-term PR", "blocks": [{"t": "p", "html": "Stem: 17-year-old post transannular repair, exercise decline, RV dilation."}, {"t": "p", "html": "Best next step: Echo/CMR, rhythm evaluation and specialist valve decision."}, {"t": "p", "html": "Mechanism / trap: Normal SpO2 does not exclude important residual disease."}]}, {"title": "Case 8 — Pulmonary atresia/MAPCAs", "blocks": [{"t": "p", "html": "Stem: Newborn with VSD-PA, ductal supply and multiple collaterals."}, {"t": "p", "html": "Best next step: PGE1 when duct-dependent, map supply and plan staged reconstruction."}, {"t": "p", "html": "Mechanism / trap: Do not close collaterals before mapping native PA supply."}]}, {"title": "Case 9 — Syndromic TOF", "blocks": [{"t": "p", "html": "Stem: TOF with palatal anomaly, hypocalcemia and infections."}, {"t": "p", "html": "Best next step: Evaluate 22q11.2 deletion and immune/calcium issues."}, {"t": "p", "html": "Mechanism / trap: Noncardiac findings can change perioperative management."}]}]}, {"id": "data", "title": "Data Interpretation", "group": "Practice", "kind": "data", "sections": [{"title": "", "blocks": [{"t": "p", "html": "<strong>Station V1</strong> — Point to the structural reason RV systolic pressure approaches LV pressure and name the flow-limiting component."}, {"t": "p", "html": "<strong>Interpretation:</strong> Large malalignment VSD equalizes RV/LV systolic pressure; RVOTO limits antegrade pulmonary flow. <em>(Linked: Figure 1 in the study notes.)</em>"}, {"t": "p", "html": "<strong>Station V2</strong> — During a spell, predict what happens to SVR, RVOTO, R-to-L shunt and murmur intensity."}, {"t": "p", "html": "<strong>Interpretation:</strong> RVOTO rises, R-to-L shunt rises, SpO2 falls, murmur may soften; raising SVR/relieving infundibular spasm helps. <em>(Linked: Figure 2 in the study notes.)</em>"}, {"t": "p", "html": "<strong>Station V3</strong> — Interpret silhouette, pulmonary vascularity and ECG expectation; give two mimics."}, {"t": "p", "html": "<strong>Interpretation:</strong> Boot silhouette + oligemia suggests TOF; expected RAD/RVH. Consider critical PS and DORV/VSD/PS as mimics. <em>(Linked: Figure 3 in the study notes.)</em>"}, {"t": "p", "html": "<strong>Station V4</strong> — Explain why PGE1 helps a newborn with TOF-pulmonary atresia but is not universally needed in stable classical TOF."}, {"t": "p", "html": "<strong>Interpretation:</strong> PGE1 maintains ductal supply when antegrade RV-to-PA flow is absent; stable nonduct-dependent TOF does not require routine PGE1. <em>(Linked: Figure 4 in the study notes.)</em>"}, {"t": "p", "html": "<strong>Station V5</strong> — <em>Data:</em> 16-year-old repaired TOF follow-up: RVEDVi 171 mL/m², severe PR, falling exercise tolerance. State the next imaging/clinical decision and why a volume threshold alone is not sufficient."}, {"t": "p", "html": "<strong>Interpretation:</strong> RVEDVi 171 with severe PR and exercise decline merits specialist CMR/valve evaluation; volume thresholds alone do not mandate surgery."}]}]}, {"id": "pearls", "title": "Pearls & Traps", "group": "Practice", "kind": "pearls", "sections": [{"title": "", "blocks": [{"t": "list", "ordered": false, "items": ["Loud VSD murmur ≠ large VSD in TOF; RVOT murmur predominates.", "Softer murmur during a spell ≠ improving obstruction.", "Oxygen alone cannot reverse anatomic R-to-L shunt.", "Acyanotic newborn does not exclude pink TOF.", "PGE1 is for suspected duct-dependent flow, not every TOF child.", "75–85% SpO2 target is for selected duct-dependent systemic lesions, not all TOF.", "Oligemia + RVH suggests TOF; oligemia + LVH/superior axis suggests tricuspid atresia.", "A single S2 is not specific for TOF.", "A boot-shaped CXR is supportive, not required for diagnosis.", "Severe pulmonary atresia may be duct- or MAPCA-dependent.", "Absent pulmonary valve syndrome may cause airway compression.", "Crossing coronary can alter RVOT incision; never ignore.", "No spell does not justify delaying elective repair beyond consensus window.", "After transannular patch, pulmonary regurgitation is a major late concern.", "CMR RV volume thresholds support but do not independently dictate pulmonary valve replacement."]}]}]}, {"id": "quizzes", "title": "Quizzes", "group": "Practice", "kind": "quizzes", "sections": []}, {"id": "recall", "title": "Active Recall", "group": "Revise", "kind": "recall", "sections": [{"title": "", "blocks": [{"t": "list", "ordered": true, "items": ["Name four TOF features.<br>Answer: VSD, overriding aorta, RVOTO, RVH.", "Which TOF feature governs cyanosis most?<br>Answer: RVOTO relative to SVR.", "Why can pink TOF occur?<br>Answer: Mild RVOTO and adequate pulmonary blood flow.", "Where is the classic systolic murmur generated?<br>Answer: Turbulence across RVOT obstruction.", "Why can murmur soften during a spell?<br>Answer: Less antegrade pulmonary flow.", "List four spell triggers.<br>Answer: Crying, fever, dehydration, defecation/feeding.", "State spell feedback cycle.<br>Answer: Adrenergic RVOTO → R-to-L shunt → hypoxemia → hyperpnea/catecholamines.", "Why knee-chest?<br>Answer: Increases SVR and favours pulmonary flow.", "What are first ABC steps in a spell?<br>Answer: Call help, calm, knee-chest, oxygen and monitor ABC.", "When can volume help?<br>Answer: Hypovolemia/poor RV filling, cautious isotonic bolus.", "Why beta-blocker?<br>Answer: Reduce dynamic infundibular spasm.", "Why phenylephrine?<br>Answer: Increase SVR to reduce R-to-L shunt.", "When is PGE1 relevant?<br>Answer: Suspected duct-dependent pulmonary flow e.g. TOF-PA.", "Major PGE1 adverse effect?<br>Answer: Apnea; prepare respiratory support.", "What is Indian elective repair timing?<br>Answer: 6–12 months stable minimally cyanosed; earlier per policy.", "When intervene early under 6 months?<br>Answer: Significant cyanosis or spells despite therapy.", "Name three palliation approaches.<br>Answer: BT shunt, ductal stent, RVOT stent; selected balloon options.", "What is MAPCA?<br>Answer: Major aortopulmonary collateral artery.", "What is absent pulmonary valve danger?<br>Answer: Dilated PAs compress airways.", "Which coronary anomaly matters?<br>Answer: LAD from RCA crossing RVOT.", "What does CXR classically show?<br>Answer: Boot heart, concave PA segment, oligemia.", "What ECG pattern fits classical TOF?<br>Answer: Right-axis deviation and RVH.", "What genetic deletion is associated?<br>Answer: 22q11.2.", "What is major postrepair valve lesion?<br>Answer: Pulmonary regurgitation and RV dilation.", "What tests support late follow-up?<br>Answer: Echo, ECG/Holter, CMR, functional assessment as indicated."]}]}, {"title": "", "blocks": [{"t": "p", "html": "Retest notification reference: the original failed-question names appear only in the post-answer explanations and notebook coverage table. They are short descriptive labels, not verified verbatim original question titles."}]}]}, {"id": "notebook", "title": "Error Notebook", "group": "Revise", "kind": "notebook", "sections": []}, {"id": "plan", "title": "Revision Plan", "group": "Revise", "kind": "plan", "sections": [{"title": "Section J — Error Notebook Coverage (Actual Library Snapshot)", "h1": "Section J — Error Notebook Coverage (Actual Library Snapshot)", "blocks": [{"t": "p", "html": "Source: NEET_SS_Error_Notebook.md, Library copy accessed 16 Oct 2026. No outcomes are invented. Retest mapping is disclosed only here, after the learner has reached the answer section."}, {"t": "table", "head": ["Extra Q", "Original failed question and notebook ID", "Recorded status / failure", "Window / next step"], "rows": [["Q76", "Day 10 Q8 — Neonatal hypoglycemia — CPS versus PES transition windows<br>ERR-D10-Q8", "RED x2", "repeat R1; update result after attempt"], ["Q77", "Day 11 Q25 — ROP — ETROP Type 1 criteria<br>ERR-D11-Q25", "AMBER active", "R1 overdue; update result after attempt"], ["Q78", "Day 11 Q46 — Corrected age versus postmenstrual age<br>ERR-D11-Q46", "AMBER active", "R1 overdue; update result after attempt"], ["Q79", "Day 11 Q55 — ROP — AAP 2018 first screening timing<br>ERR-D11-Q55", "AMBER active", "R1 overdue; update result after attempt"], ["Q80", "Day 13 Q5 — BEARS paediatric sleep history<br>ERR-D13-Q5", "AMBER active", "R1 due; update result after attempt"], ["Q81", "Day 14 Q30 — Complicated SAM — F-75 daily feed-volume calculation<br>ERR-D14-Q30", "AMBER active", "R1 due; update result after attempt"], ["Q82", "Day 5 Q53 — BPD — Jensen support-based grading<br>ERR-D5-Q53", "AMBER active", "R1 overdue; update result after attempt"], ["Q83", "Day 7 Q34 — Neonatal aEEG — seizure interpretation<br>ERR-D7-Q34", "AMBER improving", "R2 overdue; update result after attempt"], ["Q84", "Day 8 Q41 — Preterm nutrition — enteral calories and protein<br>ERR-D8-Q41", "AMBER improving", "R2 overdue; update result after attempt"]]}, {"t": "p", "html": "Additional actual Active Recall backlog: Day 11 P1/P2/P4/P5/P8/P9/P12/P13/P14/P15/P18/P19/P20 (13 prompts, R1 overdue); Day 13 P17/P18/P20/P21 (4 prompts, R1 due/overdue). These are separate recall queue items, NOT falsely counted as nine MCQ retests."}, {"t": "p", "html": "ERR-D5-Q4 remains unresolved: original clinical concept is missing in notebook; no invented retest. Day 10 Q15/Q47/Q50/Q65 and D5-Q34/D6-Q60 are improving with next R2 near 19 Oct and were not unnecessarily repeated today."}, {"t": "p", "html": "RAG status logic: RED = repeated failure (D10-Q8 x2); AMBER = first failure/uncertain or after one successful R1; GREEN only after temporally separated demonstrated retention. R1 ~24–72 h, R2 ~7 days, R3 ~21 days; actual notebook dates override defaults."}]}, {"title": "Scoring and Error Log (Learner Completes)", "h1": "Scoring and Error Log (Learner Completes)", "blocks": [{"t": "table", "head": ["Component", "Score", "Next action"], "rows": [["Base 75", "____ correct; raw +4/−1 = ____ / 300", "List wrong/guessed Q#, K/C/R/G/S, RAG"], ["9 notebook retests", "____ correct; raw +4/−1 = ____ / 36", "Update each actual ERR ID, do not erase failures"], ["8 Friday calculations", "____ / 8", "Recheck units and arithmetic"], ["5 visual/data stations", "____ / 5", "Explain pattern, mimic and next step"], ["25 Active Recall", "____ / 25", "Queue misses for R1/R2/R3"]]}]}]}, {"id": "references", "title": "References", "group": "More", "kind": "notes", "sections": [{"title": "Section K — Honest Source and Guideline Register", "h1": "Section K — Honest Source and Guideline Register", "blocks": [{"t": "table", "head": ["Source/version", "Actual consultation status", "URL / access"], "rows": [["IAP Presidential Action Plan 2026 Cardiology Ch. 03", "Read via official 20-page PDF; TOF anatomy, spell, echo, variants and follow-up", "Cited in the original draft; not re-verified here; no number in this document relies on it"], ["IAP-NNF 2026 QRG 29", "Read official 12-page PDF; cyanotic neonate assessment, PGE1 and ductal dependence", "Cited in the original draft; not re-verified here; no number in this document relies on it"], ["IAP 2026 Emergency: Approach to Cyanotic Neonate", "Located official 9-page PDF; contextual source, not line-by-line independently rechecked", "Cited in the original draft; not re-verified here; no number in this document relies on it"], ["Saxena et al. Ann Pediatr Cardiol 2019 12:254–286", "Read online consensus excerpts; timing 6–12 months and palliation/repair &lt;6 months", "https://pmc.ncbi.nlm.nih.gov/articles/PMC6716301/"], ["Tetralogy of Fallot review (PMC7807827)", "Read accessible review excerpts; spell physiology, SVR and dynamic obstruction; international supplementary", "https://pmc.ncbi.nlm.nih.gov/articles/PMC7807827/"], ["Nelson Textbook of Pediatrics, 22e", "Required primary conceptual reference; full text not accessed; NOT cited as directly verified", "Unavailable for direct source verification"], ["OP Ghai Essential Pediatrics", "Complementary Indian reference; text not accessed", "Unavailable for direct source verification"], ["Cloherty and Stark Manual of Neonatal Care", "Neonatal specialty reference; text not accessed", "Unavailable for direct source verification"], ["Marrow NEET-SS Paediatrics / PrepLadder NEET-SS Pediatrics", "Optional paid notes not accessed, copied or implied consulted", "Unavailable subscription content"]]}, {"t": "p", "html": "Source status: The 2019 Indian consensus (Saxena et al., Ann Pediatr Cardiol 2019;12:254–286, DOI:10.4103/apc.APC_32_19) is the identified reference for Indian TOF timing and long-term follow-up. Claimed 2026 IAP/IAP-NNF source editions have not been independently authenticated. Nelson 22e, OP Ghai and Cloherty/Stark are reference priorities but were not directly checked in this revision. Marrow and PrepLadder paid material was not accessed. Use authenticated current protocols for emergency drug dosing."}]}, {"title": "Section R — Five-Stage Consolidated Release Review", "h1": "Section R — Five-Stage Consolidated Release Review", "blocks": [{"t": "p", "html": "Stage 1 — Rank/examiner: 75 base questions and nine notebook retests were reviewed for option relevance, comparison class and answer uniqueness across multiple editorial passes. This final pass materially rewrote distractors in 26 questions: Q21, Q35, Q36, Q37, Q38, Q39, Q40, Q41, Q42, Q43, Q45, Q46, Q47, Q55, Q65, Q66, Q67, Q76, Q77, Q78, Q79, Q80, Q81, Q82, Q83, Q84. Earlier V7–V9 revisions are retained. Difficulty tags are editorial, not psychometrically validated."}, {"t": "p", "html": "Stage 2 — Content: five-hour deep dives and existing conceptual sections, two clinical algorithms, nine clinical cases, five visual/data stations, traps, active-recall items and calculation problems retained; no new Day 19 lesion deep dive introduced."}, {"t": "p", "html": "Stage 3 — Sources independently checked for applicable claims: Saxena et al., Indian consensus (2019, published in Indian Heart Journal/Annals of Pediatric Cardiology) for TOF management and surgery; PES recommendations (2015) and CPS statement for 48/72-h hypoglycemia windows; AAP Pediatrics 2018 ROP screening schedule; Jensen et al. 2019 BPD support-based grading. Clinician judgment and latest institutional policies prevail. Nelson 22nd, OP Ghai and Cloherty full books, Marrow and PrepLadder proprietary materials were NOT directly accessed in this review. Not every statement in the inherited question bank has a claim-specific primary citation; do not equate this source sampling with full textbook validation."}, {"t": "p", "html": "Stage 4 — Automated key and explanation regression: all 84 items retain exactly four options and four option-specific explanations; every key points to the ✓ rationale; all numerical arithmetic retested programmatically. The independently authored source register distinguishes confirmed sources from unavailable sources. Remaining clinical ambiguity cannot be guaranteed absent external specialist verification."}, {"t": "p", "html": "Stage 5 — DOCX rendered to page images and inspected in contact sheets for gross layout issues; critical pages additionally checked at native resolution. Question counts, difficulty groups, keys, explanation blocks and diagrams are regression-tested after editing."}]}, {"title": "Verified public references and limitations", "h1": "", "blocks": [{"t": "list", "ordered": false, "items": ["Saxena A et al. Indian Heart Journal 2019;71:207–223. https://pmc.ncbi.nlm.nih.gov/articles/PMC6796629/ — TOF repair timing, palliation, cyanotic-spell algorithm, follow-up.", "Saxena A et al. Annals of Pediatric Cardiology 2019;12:254–286. https://pmc.ncbi.nlm.nih.gov/articles/PMC6716301/ — pulmonary valve replacement considerations and TOF follow-up.", "Pediatric Endocrine Society: https://pmc.ncbi.nlm.nih.gov/articles/PMC11891912/ — evaluation for persistent neonatal hypoglycemia at ≥48 h in high-risk infants.", "Canadian Paediatric Society: https://cps.ca/en/documents/position/newborns-at-risk-for-low-blood-glucose — transitional period up to 72 h.", "AAP Pediatrics 2018 ROP screening: https://publications.aap.org/pediatrics/article/142/6/e20183061/37478/Screening-Examination-of-Premature-Infants-for — 24 weeks birth GA: initial exam 31 weeks PMA.", "Jensen EA et al. AJRCCM 2019: https://pmc.ncbi.nlm.nih.gov/articles/PMC6775872/ — grade 2 BPD includes CPAP or NIPPV at 36 weeks PMA."]}]}, {"title": "Answer alignment correction register", "h1": "", "blocks": [{"t": "p", "html": "Final independent answer-versus-option semantic inspection identified 10 questions in which an earlier distractor revision left the stated answer letter attached to an incorrect text. For Q10, Q16, Q22, Q23, Q25, Q26, Q27, Q31, Q44 and Q54, the clinically intended correct choice was restored under its existing letter; the displaced distractor and its explanation were also moved. This substantive defect was not detectable by counting answer keys alone. All affected question and rationale blocks require post-edit regression."}]}, {"title": "Section T — Final Five-Stage QA Decision", "h1": "Section T — Final Five-Stage QA Decision", "blocks": [{"t": "p", "html": "Stage 1: Rank-focused review completed through V7–V9 revisions and current corrections to option plausibility; foundational items retained at their appropriate difficulty. No psychometric field validation is claimed."}, {"t": "p", "html": "Stage 2: Five-hour timetable corrected to 300 minutes; coverage audit retains all original topics, 75 questions, nine notebook retests, eight Friday calculations, 25 recall prompts, cases, diagrams and algorithms."}, {"t": "p", "html": "Stage 3: Available primary/official references compared for management timing, acute spell approach, 2018 AAP ROP screening, ETROP criteria, CPS/PES time windows and Jensen BPD definitions. No access claimed to the full Nelson 22e, OP Ghai, Cloherty, Marrow or PrepLadder texts. No claim of clinical human certification."}, {"t": "p", "html": "Stage 4: Independent AI reasoning ledger Q01–Q84 compared to the answer key; 10 legacy misaligned answer-option texts corrected and corresponding rationales updated. Arithmetic independently recalculated; notebook mappings retained with disclosed backlog."}, {"t": "p", "html": "Stage 5: All counts, options, marked explanations and image counts rechecked after editing; DOCX rendered to page images and visually reviewed for gross clipping, overflow and broken diagrams. Any post-render edit requires re-render."}, {"t": "p", "html": "Residual caveat: This is a high-rigor educational revision, not a guarantee that all clinical recommendations reflect the latest locally adopted protocol. Consult current institutional pediatric cardiac guidance when making clinical decisions."}]}]}], "quizSets": [{"k": 1, "from": 1, "to": 17, "n": 17}, {"k": 2, "from": 18, "to": 34, "n": 17}, {"k": 3, "from": 35, "to": 51, "n": 17}, {"k": 4, "from": 52, "to": 68, "n": 17}, {"k": 5, "from": 69, "to": 84, "n": 16}], "mcqCount": 84, "calc": {"n": 8, "href": "calc.html"}};
